def _follow_update_sort_key(self, pair):
    item, history = pair
    conflict = bool(isinstance(history, dict) and history.get("_follow_history_conflict"))
    if conflict:
        group = 0
    elif str(item.get("check_error") or ""):
        group = 5
    elif self._has_follow_update(item, history):
        group = 1
    elif self._history_can_resume(history or item):
        group = 2
    elif str(item.get("next_air_date") or ""):
        group = 3
    else:
        group = 4
    return (
        group,
        str(item.get("next_air_date") or "9999-99-99"),
        str(item.get("title") or ""),
        self._positive_int(item.get("tmdb_id"), 0),
    )

