def _follow_preheat_card(self):
    progress = self._follow_preheat_snapshot()
    total = progress["total"]
    ready = progress["ready"]
    processed = progress["processed"]
    if progress["running"]:
        remark = "预热中 · 已处理 %d/%d · 可直接播放 %d/%d" % (
            processed, total, ready, total,
        )
        if progress["route_jobs"]:
            remark += " · 线路验证 %d" % progress["route_jobs"]
    elif total and processed >= total and progress["started_at"]:
        remark = "预热完成 · 可直接播放 %d/%d" % (ready, total)
        if ready < total:
            remark += " · %d 项未找到可用线路" % (total - ready)
        else:
            remark += " · 线路失效后自动刷新"
    elif total:
        remark = "可直接播放 %d/%d · 点击预热全部追更剧集" % (ready, total)
    else:
        remark = "当前没有可预热的追更剧集"
    return {
        "vod_id": self.FOLLOW_PREHEAT_ACTION,
        "vod_name": "主动预热追更线路",
        "vod_pic": "",
        "vod_remarks": remark,
        "action": self.FOLLOW_PREHEAT_ACTION,
    }

def _start_follow_preheat(self):
    items = [
        dict(item) for item in (self._follow_memory.get("items") or {}).values()
        if isinstance(item, dict) and str(item.get("title") or "").strip()
    ]
    if not items:
        result = json.dumps({"msg": "当前没有可预热的追更剧集"}, ensure_ascii=False)
        return self._remember_follow_action_result(result, "preheat")
    if not (
            self._alist_tvbox_plugin and self.route_preheat and self.atvp_api
            and self.atvp_token and self._atvp_session is not None):
        result = json.dumps({"msg": "主动预热未启动：AList-TVBox播放通道尚未就绪"}, ensure_ascii=False)
        return self._remember_follow_action_result(result, "preheat")
    progress = self._start_follow_preheat_all(items)
    card = self._follow_preheat_card()
    if progress.get("accepted"):
        message = "主动预热已开始 · " + str(card.get("vod_remarks") or "后台处理中")
        self._set_follow_action_status("running", message, "preheat")
        self._refresh_follow_categories()
        return json.dumps({"msg": message}, ensure_ascii=False)
    message = "主动预热正在进行 · " + str(card.get("vod_remarks") or "请稍后查看")
    result = json.dumps({"msg": message}, ensure_ascii=False)
    return self._remember_follow_action_result(result, "preheat")

def _history_alert_cards(self):
    status = self._atvp_status.get("sync") if isinstance(self._atvp_status, dict) else None
    if not isinstance(status, dict) or status.get("state") not in ("running", "failed"):
        return []
    state = str(status.get("state") or "")
    message = str(status.get("message") or "").strip()
    updated_at = self._positive_int(status.get("updated_at"), 0)
    timestamp = time.strftime("%m-%d %H:%M", time.localtime(updated_at)) if updated_at else ""
    return [{
        "vod_id": self.ATVP_SYNC_ACTION,
        "vod_name": "History 正在同步" if state == "running" else "History 同步失败",
        "vod_pic": "",
        "vod_remarks": message + ((" · " + timestamp) if timestamp else ""),
        "action": self.ATVP_SYNC_ACTION,
    }]

