def _follow_item_key(self, item):
    if not isinstance(item, dict):
        return ""
    tmdb_id = self._positive_int(item.get("tmdb_id"), 0)
    if tmdb_id:
        return str(tmdb_id)
    source_id = str(item.get("source_id") or item.get("local_source_id") or "").strip()
    if re.match(r"^local:tv:[0-9a-f]{24}$", source_id):
        return source_id
    douban_id = self._subject_id(item.get("douban_id"))
    return "douban:" + douban_id if douban_id else ""

def _follow_item_source_aliases(self, item):
    aliases = set()
    if not isinstance(item, dict):
        return aliases
    for value in (item.get("source_id"), item.get("local_source_id")):
        value = str(value or "").strip()
        if value:
            aliases.add(value)
    for value in item.get("source_aliases") or []:
        value = str(value or "").strip()
        if value:
            aliases.add(value)
    tmdb_id = self._positive_int(item.get("tmdb_id"), 0)
    if tmdb_id:
        aliases.add("tmdb:tv:%s" % tmdb_id)
    return aliases

def _follow_item_lookup(self, raw_id):
    raw = unquote(str(raw_id or "").strip())
    items = self._follow_memory.get("items") if isinstance(self._follow_memory, dict) else {}
    if not isinstance(items, dict):
        return "", None
    numeric = self._positive_int(raw, 0)
    direct_key = str(numeric) if numeric else raw
    direct = items.get(direct_key)
    if isinstance(direct, dict):
        return direct_key, direct
    for key, item in items.items():
        if isinstance(item, dict) and raw in self._follow_item_source_aliases(item):
            return str(key), item
    return "", None

def _follow_progress_rank(self, item):
    if not isinstance(item, dict):
        return (0, 0, 0, 0)
    return (
        self._positive_int(item.get("history_source_updated_at_ms"), 0),
        self._positive_int(item.get("history_updated_at"), 0),
        self._episode_rank(item.get("history_episode") or item.get("tracked_episode")),
        self._positive_int(item.get("history_position"), 0),
    )

def _merge_follow_identity_items(self, current, incoming):
    current = dict(current or {})
    incoming = dict(incoming or {})
    output = dict(current)
    output.update(incoming)
    progress = incoming if self._follow_progress_rank(incoming) >= self._follow_progress_rank(current) else current
    for key in (
            "history_episode", "history_position", "history_duration", "history_vod_name",
            "history_completed", "history_updated_at", "history_source_updated_at_ms",
            "history_playback", "tracked_episode", "seen_episode", "seen_source",
            "last_play_route", "alist_vod_id", "alist_resource_mode",
            "alist_resource_provider", "binding_updated_at"):
        if key in progress:
            output[key] = progress[key]
    aliases = self._follow_item_source_aliases(current) | self._follow_item_source_aliases(incoming)
    if aliases:
        output["source_aliases"] = sorted(aliases)
    return output

def _follow_state_cards(self, include_pending=False):
    cards = []
    with self._follow_action_state_lock:
        state = dict(self._follow_action_state or {})
        pending = dict(state.get("pending") or {})
        last = dict(state.get("last") or {})
    requested_at = self._positive_int(pending.get("requested_at"), 0)
    if include_pending and pending and requested_at and int(time.time()) - requested_at <= self.FOLLOW_CONFIRM_TTL:
        operation = str(pending.get("operation") or "")
        item_key = str(pending.get("item_key") or pending.get("tmdb_id") or "").strip()
        nonce = str(pending.get("nonce") or "")
        title = str(pending.get("title") or item_key)
        if operation in ("seen", "remove") and item_key and nonce:
            label = "标记当前更新已看完" if operation == "seen" else "取消追更"
            execute = self.FOLLOW_EXECUTE_PREFIX + "%s:%s:%s" % (nonce, operation, item_key)
            cards.extend([
                {
                    "vod_id": execute,
                    "vod_name": "确认%s：%s" % (label, title),
                    "vod_pic": "",
                    "vod_remarks": "待确认 · %s分钟内有效" % max(1, self.FOLLOW_CONFIRM_TTL // 60),
                    "action": execute,
                },
                {
                    "vod_id": self.FOLLOW_CONFIRM_CANCEL_PREFIX + nonce,
                    "vod_name": "放弃本次操作",
                    "vod_pic": "",
                    "vod_remarks": title,
                    "action": self.FOLLOW_CONFIRM_CANCEL_PREFIX + nonce,
                },
            ])
    message = str(last.get("message") or "").strip()
    if message:
        state_name = str(last.get("state") or "info")
        label = {"done": "操作成功", "failed": "操作失败", "running": "处理中"}.get(state_name, "操作状态")
        updated_at = self._positive_int(last.get("updated_at"), 0)
        timestamp = time.strftime("%m-%d %H:%M", time.localtime(updated_at)) if updated_at else ""
        cards.append({
            "vod_id": self.FOLLOW_STATUS_ACK_ACTION,
            "vod_name": label,
            "vod_pic": "",
            "vod_remarks": message + ((" · " + timestamp) if timestamp else ""),
            "action": self.FOLLOW_STATUS_ACK_ACTION,
        })
    return cards

